function serviceError(status, body) {
	const code = body?.error?.code ?? "unknown_error";
	const err = new Error(body?.error?.message ?? `request failed with status ${status}`);
	err.name = "ServiceError";
	err.status = status;
	err.code = code;
	return err;
}

export function createEventConsumer(service, options) {
	const consumerId = options.consumerId;
	const handle = options.handle;
	const batchSize = options?.batchSize ?? 4;

	async function run() {
		const cpRes = await service.request("GET", `/checkpoints/${consumerId}`);
		let lastHandledSeq = null;
		if (cpRes.status === 200) {
			lastHandledSeq = Number(cpRes.body.after);
		} else if (cpRes.status !== 404) {
			throw serviceError(cpRes.status, cpRes.body);
		}

		let cursor = lastHandledSeq === null ? undefined : String(lastHandledSeq);
		for (;;) {
			const query = { limit: batchSize };
			if (cursor !== undefined) query.after = cursor;
			const res = await service.request("GET", "/events", { query });
			if (res.status !== 200) throw serviceError(res.status, res.body);
			const { events, nextAfter } = res.body;

			for (const event of events) {
				if (lastHandledSeq !== null && event.seq <= lastHandledSeq) continue;
				await handle(event);
				lastHandledSeq = event.seq;
				const putRes = await service.request("PUT", `/checkpoints/${consumerId}`, {
					body: { after: String(lastHandledSeq) },
				});
				if (putRes.status !== 200) throw serviceError(putRes.status, putRes.body);
			}

			if (nextAfter === null || nextAfter === undefined) break;
			cursor = nextAfter;
		}
	}

	return { run };
}
